#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> ones;
    for (int i = 1; i <= n; ++i) {
        int a;
        cin >> a;
        if (a == 1) {
            ones.push_back(i);
        }
    }

    long long total = 0;
    int k = ones.size();

    for (int i = 0; i < k; ++i) {
        long long prev = (i == 0) ? 0 : ones[i - 1];
        long long next = (i == k - 1) ? (n + 1) : ones[i + 1];

        long long left_choices = ones[i] - prev;
        long long right_choices = next - ones[i];

        total += left_choices * right_choices;
    }

    cout << total << "\n";

    return 0;
}
